// Colours from SPRITE_TINT on are tint slots (light, mid, dark).
#define SPRITE_TINT 19
static GColor sprite_palette(uint8_t i) {
  switch (i) {
    case 0: return GColorBlack;
    case 1: return GColorWhite;
    case 2: return GColorLightGray;
    case 3: return GColorDarkGray;
    case 4: return GColorRed;
    case 5: return GColorDarkCandyAppleRed;
    case 6: return GColorSunsetOrange;
    case 7: return GColorYellow;
    case 8: return GColorChromeYellow;
    case 9: return GColorWindsorTan;
    case 10: return GColorCeleste;
    case 11: return GColorMediumSpringGreen;
    case 12: return GColorJaegerGreen;
    case 13: return GColorDarkGreen;
    case 14: return GColorMintGreen;
    case 15: return GColorInchworm;
    case 16: return GColorKellyGreen;
    case 17: return GColorGreen;
    case 18: return GColorIslamicGreen;
    default: return GColorClear;
  }
}

